    std::uint8_t aDomainWordMatrixArgD = pConstants->mMatrixArgD;

    //
    // src: [$abjuration]
    // dst: [$aether]
    //
    TwistExpander_Polaris_Arx::KDF_C_A_E(PARAMS_KDF);

    //
    // src: [$aether]
    // dst: [$lunar]
